import React from "react";
import { HomeBox } from "../components";
import { Helmet } from "react-helmet-async";

const Home = ({
	isFetching,
	homePageData,
	homeLoadingData,
	setUseDisplayStores,
	displayStores,
	setPageTarget,
	pageTarget,
}) => {
	return (
		<>
			<Helmet>
				<title>{`${homePageData?.platform_info?.name}`}</title>
				<meta
					name='description'
					content={`${homePageData?.platform_info?.description}`}
				/>
			</Helmet>
			<HomeBox
				isFetching={isFetching}
				homePageData={homePageData}
				homeLoadingData={homeLoadingData}
				pageTarget={pageTarget}
				setPageTarget={setPageTarget}
				displayStores={displayStores}
				setUseDisplayStores={setUseDisplayStores}
			/>
		</>
	);
};

export default Home;
