import React from "react";

// third party
import DOMPurify from "dompurify";
import { Helmet } from "react-helmet-async";

// Components
import LoadingBox from "../LoadingBox/LoadingBox";
import PageTitle from "../PagesTitle/PageTitle";

import "./WebsitePagesBox.css";

const WebsitePagesBox = ({
	platformName,
	pageName,
	shortDescription,
	Description,
	Loading,
}) => {
	return (
		<>
			<Helmet>
				<title>{`${platformName} | ${pageName}`} </title>
				<meta name='description' content={shortDescription} />
			</Helmet>
			<div className='atlbha-academy'>
				<div className='container'>
					{Loading ? (
						<LoadingBox />
					) : (
						<>
							<PageTitle title={pageName} />
							<div className='content'>
								<p
									className={
										pageName === "الدورات التدريبية"
											? "academy-content"
											: "policy-content"
									}
									dangerouslySetInnerHTML={{
										__html: DOMPurify.sanitize(Description),
									}}
								/>
							</div>
						</>
					)}
				</div>
			</div>
		</>
	);
};

export default WebsitePagesBox;
