import React from "react";
import { FloatingWhatsApp } from "react-floating-whatsapp";
import "./FloatingWhatsappIcon.css";

const FloatingWhatsappIcon = ({ platformInfo, platformLogo }) => {
	return (
		<FloatingWhatsApp
			allowEsc
			allowClickAway
			notification
			notificationSound
			notificationDelay={10}
			chatboxStyle={{
				borderRadius: "8px",
				direction: "ltr",
			}}
			className='floating-whatsapp-icon'
			accountName={platformInfo?.name}
			avatar={platformLogo}
			statusMessage='سيتم التواصل في أقرب وقت'
			chatMessage='السلام عليكم ورحمة اللّه وبركاته كيف يمكنني مساعدتك؟'
			placeholder='أكتب رسالتك هنا...'
			phoneNumber={platformInfo?.phonenumber}
		/>
	);
};

export default FloatingWhatsappIcon;
