import React, { useEffect, useState } from "react";
import { Suspense } from "react";
import { BrowserRouter, Route, Routes } from "react-router-dom";

import { ToastContainer } from "react-toastify";

// Import Styles Files
import "react-toastify/dist/ReactToastify.css";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle";

import {
	FloatingWhatsappIcon,
	FooterOverlay,
	Header,
	LoadingPage,
	NotFoundPage,
	WhatWeOfferDetails,
} from "../components";
import { Home } from "./index";

// RTK Query
import { useGetHomePageDataQuery } from "../RTK/Api/homeApi";

// use spouse to handle lazy loading..
const Blog = React.lazy(() => import("./Blog"));

const BlogDetail = React.lazy(() => import("./BlogDetail"));
const WebsitePages = React.lazy(() => import("./WebsitePages"));
const Services = React.lazy(() => import("./Services/Services"));
const PackagesPage = React.lazy(() => import("./PackagesPage/PackagesPage"));

const ProductsPage = React.lazy(() => import("./ProductsPage"));
const SuccessCheckOut = React.lazy(() =>
	import("../components/PaymentStatus/SuccessCheckout")
);
const FailedCheckout = React.lazy(() =>
	import("../components/PaymentStatus/FailedCheckout")
);

/* Business Trip Dubai content */
const BusinessStorePage = React.lazy(() =>
	import("./BusinessFlights/BusinessStorePage")
);

// const ContactUs = React.lazy(() => import("./ContactUs"));
const Faqs = React.lazy(() => import("./Faqs/Faqs"));

const AllPages = () => {
	// to handle pagination of stores
	const [pageTarget, setPageTarget] = useState(1);
	const [displayStores, setUseDisplayStores] = useState(12);

	const {
		data: homePageData,
		isLoading,
		isFetching,
	} = useGetHomePageDataQuery({
		page: pageTarget,
		number: displayStores,
	});

	localStorage.setItem("headerLogo", homePageData?.logo);

	const updateFavicons = (faviconUrl) => {
		const links = document.querySelectorAll('link[rel*="icon"]');
		links.forEach((link) => {
			link.href = faviconUrl;
		});
	};

	useEffect(() => {
		if (homePageData?.favicon) {
			updateFavicons(homePageData.favicon);
		}
	}, [homePageData]);

	return (
		<>
			<div className='w-100 overflow-hidden'>
				<BrowserRouter
					future={{
						v7_startTransition: true,
						v7_relativeSplatPath: true,
					}}>
					<Header homeFooter={homePageData?.footer} logo={homePageData?.logo} />

					<ToastContainer
						rtl
						draggable
						closeOnClick
						pauseOnHover
						autoClose={5000}
						pauseOnFocusLoss
						position='top-right'
						newestOnTop={false}
						hideProgressBar={false}
						theme='colored'
						style={{ fontSize: "14px", color: "#000", whiteSpace: "normal" }}
					/>

					<Routes>
						<Route
							path=''
							element={
								<Suspense fallback={<LoadingPage />}>
									<Home
										isFetching={isFetching}
										homePageData={homePageData}
										homeLoadingData={isLoading}
										pageTarget={pageTarget}
										setPageTarget={setPageTarget}
										displayStores={displayStores}
										setUseDisplayStores={setUseDisplayStores}
									/>
								</Suspense>
							}
						/>

						<Route
							path='/services'
							element={
								<Suspense fallback={<LoadingPage />}>
									<Services platformName={homePageData?.platform_info?.name} />
								</Suspense>
							}
						/>
						<Route
							path='/success'
							element={
								<Suspense>
									<SuccessCheckOut
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>
						<Route
							path='/failed'
							element={
								<Suspense>
									<FailedCheckout
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>
						<Route
							path='/business-store/:id'
							element={
								<Suspense>
									<BusinessStorePage />
								</Suspense>
							}
						/>

						{/* Package Info */}
						<Route
							path='/package-info/:id'
							element={
								<Suspense>
									<BusinessStorePage
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>

						<Route
							path='/packages'
							element={
								<Suspense fallback={<LoadingPage />}>
									<PackagesPage
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>
						<Route
							path='/blog'
							element={
								<Suspense fallback={<LoadingPage />}>
									<Blog platformName={homePageData?.platform_info?.name} />
								</Suspense>
							}
						/>
						<Route
							path='/post/:id/:title'
							element={
								<Suspense fallback={<LoadingPage />}>
									<BlogDetail
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>

						<Route
							path='/all-products/:id/:title'
							element={
								<Suspense fallback={<LoadingPage />}>
									<ProductsPage
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>
						<Route
							path='/all-products'
							element={
								<Suspense fallback={<LoadingPage />}>
									<ProductsPage
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>

						<Route
							path='/Page/:id/:title'
							element={
								<Suspense fallback={<LoadingPage />}>
									<WebsitePages
										platformName={homePageData?.platform_info?.name}
									/>
								</Suspense>
							}
						/>
						<Route
							path='/whatWeOffer/:title'
							element={
								<WhatWeOfferDetails
									platformName={homePageData?.platform_info?.name}
								/>
							}
						/>

						{/*	<Route
							path='/contact-us'
							element={
								<Suspense>
									<ContactUs />
								</Suspense>
							}
						/>*/}

						<Route
							path='/faqs'
							element={
								<Suspense fallback={<LoadingPage />}>
									<Faqs platformName={homePageData?.platform_info?.name} />
								</Suspense>
							}
						/>

						<Route path='*' element={<NotFoundPage />} />
					</Routes>

					<FooterOverlay
						platformName={homePageData?.platform_info?.name}
						registrationMarketer={homePageData?.registration_marketer}
						linkWebsite={homePageData?.website_socialmedia}
						logoFooter={homePageData?.logo_footer}
						homeFooter={homePageData?.footer}
					/>
				</BrowserRouter>

				<FloatingWhatsappIcon
					platformInfo={homePageData?.platform_info}
					platformLogo={homePageData?.logo}
				/>
			</div>
		</>
	);
};

export default AllPages;
