import { createApi } from "@reduxjs/toolkit/query/react";
import axiosBaseQuery from "../../API/axiosBaseQuery";

// Create API slice
export const termsApi = createApi({
	reducerPath: "termsApi",

	// base url
	baseQuery: axiosBaseQuery({
		baseUrl: "https://backend.store-revo.com/api/",
	}),

	tagTypes: ["terms"],

	endpoints: (builder) => ({
		// get services Data endpoint..
		getTermsPageCategory: builder.query({
			query: () => ({
				url: `selector/pageCategories`,
			}),

			// Pick out data and prevent nested properties in a hook or selector
			transformResponse: (response, meta, arg) => response.data.categories,

			providesTags: ["terms"],
		}),
		// get services Data endpoint..
		getTermsPageByPageCategoryId: builder.query({
			query: ({ id }) => ({
				url: `pagesByCategory/${id}`,
			}),

			// Pick out data and prevent nested properties in a hook or selector
			transformResponse: (response, meta, arg) => response.data.pages[0],

			providesTags: ["terms"],
		}),
	}),
});

// Export endpoints and hooks
export const {
	useGetTermsPageCategoryQuery,
	useGetTermsPageByPageCategoryIdQuery,
} = termsApi;
